import json
import re

def parse_game_data(json_str):
    """
    解析游戏角色交易数据
    """
    try:
        # 解析外层JSON
        outer_data = json.loads(json_str)
        
        # 获取内层data字段并解析
        inner_json_str = outer_data['rsp']['response']['data']
        inner_data = json.loads(inner_json_str)
        
        # 获取角色列表
        role_list_str = inner_data['data']['roleList']
        role_list = json.loads(role_list_str)
        
        print("=" * 60)
        print("游戏代练角色信息解析结果")
        print("=" * 60)
        
        # 统计信息
        total_roles = len(role_list)
        total_price = 0
        platform_stats = {}
        channel_stats = {}
        price_range = []
        
        print(f"\n总共找到 {total_roles} 个游戏代练角色：\n")
        
        for i, role in enumerate(role_list, 1):
            print(f"--- 角色 {i} ---")
            
            # 基本信息
            print(f"平台ID: {role['platformID']}")
            print(f"渠道ID: {role['channelID']}")
            print(f"分区ID: {role['partitionID']}")
            print(f"角色ID: {role['roleID']}")
            print(f"玩家名称: {role.get('playerName', '未命名')}")
            
            # 游戏属性
            game_summary = role['gameSummary']
            print(f"战力: {game_summary['CombatPower']:,}")
            print(f"等级: {game_summary['Level']}级")
            print(f"家园等级: {game_summary['HouselandLevel']}级")
            print(f"家园积分: {game_summary['HouselandPoint']:,}")
            print(f"国家: {game_summary['PlayerNation']}")
            print(f"头像ID: {game_summary['HeadId']}")
            print(f"自定义ID: {game_summary['CustomXId']}")
            
            # 标签信息
            game_tags_str = role['gameTags']
            try:
                game_tags = json.loads(game_tags_str)
                tags = game_tags.get('allTags', [])
                tag_names = [tag['name'] for tag in tags]
                print(f"标签: {', '.join(tag_names) if tag_names else '无'}")
            except:
                print("标签: 解析失败")
            
            # 交易信息
            price = role['price']
            total_price += price
            price_range.append(price)
            
            print(f"价格: {price:,}")
            print(f"收藏数: {role['favAmount']}")
            print(f"是否可议价: {'是' if role['allowBargain'] else '否'}")
            print(f"议价状态: {role['bargainStatus']}")
            print(f"商品状态: {role['commodityStatus']}")
            print(f"商品编号: {role['commoditySN']}")
            
            # 统计数据
            platform = role['platformID']
            channel = role['channelID']
            platform_stats[platform] = platform_stats.get(platform, 0) + 1
            channel_stats[channel] = channel_stats.get(channel, 0) + 1
            
            print("-" * 40)
        
        # 输出统计信息
        print("\n" + "=" * 60)
        print("统计信息")
        print("=" * 60)
        
        print(f"总角色数: {total_roles}")
        print(f"总价: {total_price:,}")
        print(f"平均价: {total_price/total_roles:,.0f}")
        print(f"最高价: {max(price_range):,}")
        print(f"最低价: {min(price_range):,}")
        
        print("\n平台分布:")
        for platform, count in platform_stats.items():
            print(f"  {platform}: {count}个")
            
        print("\n渠道分布:")
        for channel, count in channel_stats.items():
            print(f"  {channel}: {count}个")
            
        # 按价格排序显示前5名
        print("\n价格排名前5的角色:")
        sorted_roles = sorted(enumerate(role_list), key=lambda x: x[1]['price'], reverse=True)[:5]
        for i, (index, role) in enumerate(sorted_roles, 1):
            game_summary = role['gameSummary']
            print(f"{i}. 战力{game_summary['CombatPower']:,} | 价格{role['price']:,} | 分区{role['partitionID']}")
            
    except Exception as e:
        print(f"解析出错: {str(e)}")
        print("错误详情:")
        import traceback
        traceback.print_exc()

